-- Content-only update for mobile-development with exact-original text preflight.
BEGIN;
CREATE TEMP TABLE legacy_guides(payload jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO legacy_guides(payload) VALUES ($legacy_payload$[{"slug":"mobile-development","task_number":1,"title":"Expo Setup","old_description":"[[AZ]]\nExpo əsaslı mobil layihəni qur, cihazda işə sal və başlanğıc quraşdırmanı təkrarlana bilən et.\n\n[[EN]]\nSet up an Expo mobile project, run it on a device, and make the initial setup reproducible.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nTelefonda və ya emulatorda açıla bilən sadə mobil tətbiq yaradacaqsan. Layihəni sıfırdan qurub işə salma qaydasını sənədləşdirəcəksən.\n\n## 2. Başlamazdan əvvəl\nJavaScript-ə ilkin bələdlik, Node.js/npm, VS Code və terminaldan istifadə. Telefonda Expo Go istifadə edə bilərsən; Android emulatoru üçün Android Studio lazım ola bilər.\n\n## 3. Addım-addım icra\n1. GitHub-da özünə boş `mobile-starter-app` repo-su yarat. Sıfırdan başla.\n2. Node.js LTS və VS Code quraşdırıldığını yoxla.\n3. Terminalda `npx create-expo-app@latest mobile-starter-app --template blank-typescript` əmrini işlət və layihə qovluğuna keç.\n4. `npx expo start` ilə tətbiqi başlat. QR kodu Expo Go ilə oxut və ya emulator aç.\n5. Başlanğıc ekranda tətbiqin adını və “Salam!” mesajını göstər.\n6. `README.md`-də quraşdırma və işə salma addımlarını yaz. Gizli açar və parol əlavə etmə.\n7. Layihəni öz GitHub repo-na göndər və tətbiqin açıldığını göstərən screenshot əlavə et.\n\n## 4. Konkret nümunə və izah\nLayihəni yaratdıqdan sonra terminalda `cd mobile-starter-app`, sonra `npx expo start` işlət. Eyni adlı repo-nu əvvəl klonlamısansa, ikinci eyniadlı qovluq yaratmadığını yoxla. Telefon və development server eyni uyğun şəbəkədə olmalıdır.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işləyən Expo/TypeScript tətbiqi, quraşdırma təlimatlı README və tətbiqin açıldığını göstərən screenshot.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nTelefon/emulator tətbiqi açır və dəyişdirdiyin başlıq görünür. README-də qovluq, quraşdırma, start əmri və sınanmış cihaz/mühit qeyd edilib.\n\n[[EN]]\n## 1. Goal\nCreate a simple mobile app that opens on a phone or emulator. Set it up from scratch and document how to run it.\n\n## 2. Before you start\nIntroductory JavaScript, Node.js/npm, and basic VS Code and terminal use. Expo Go works on a phone; Android Studio may be needed for an emulator.\n\n## 3. Step-by-step work\n1. Create your own empty GitHub repository named `mobile-starter-app`. Start from scratch.\n2. Check that Node.js LTS and VS Code are installed.\n3. Run `npx create-expo-app@latest mobile-starter-app --template blank-typescript` in the terminal and enter the project folder.\n4. Start the app with `npx expo start`. Scan the QR code with Expo Go or open an emulator.\n5. Show the app name and a “Hello!” message on the home screen.\n6. Document setup and startup in `README.md`. Do not add secrets or passwords.\n7. Push the project to your own GitHub repository and add a screenshot showing the app running.\n\n## 4. Concrete example and explanation\nAfter creating the project run `cd mobile-starter-app`, then `npx expo start`. Avoid nesting a second folder with the same name if you already cloned the repository. The phone must reach the development server.\n\n## 5. What to submit\nYour own GitHub repository link, working Expo/TypeScript app, setup README, and a screenshot of the running app.\n\n## 6. How to check your work\nThe app opens on a phone/emulator and shows your edited title. Document folder, install/start commands, and tested device/environment.","new_description":"[[AZ]]\nExpo əsaslı mobil layihəni qur, cihazda işə sal və başlanğıc quraşdırmanı təkrarlana bilən et.\n\nPulsuz alətlər: Node.js (free), Expo Go / Expo CLI (free local), GitHub Free. Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nSet up an Expo mobile project, run it on a device, and make the initial setup reproducible.\n\nFree tools: Node.js (free), Expo Go / Expo CLI (free local), GitHub Free. The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** Pulsuz Expo Go ilə 'My Tasks' ekranını real telefonda aç; mağazada yayımlama lazım deyil.\n\n## Pulsuz platformalar və istifadə qaydası\n- **Node.js (free)** — https://nodejs.org. Lokal JavaScript/TypeScript mühiti qur, paketləri quraşdır və development server aç.\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. `npx expo start` ilə lokal React Native demo aç, Expo Go-da test et; app-store/EAS ödənişi lazım deyil.\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / mobile-development / task-1` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. Node.js və Expo layihəsini lokal quraşdır, `npx expo start` işə sal. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. Expo Go ilə QR/kabel vasitəsilə demo aç və bir əsas ekran göstər. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. README-də cihaz, əmrlər və xəta həllini yaz; ödənişli EAS build məcburi deyil. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: Pulsuz Expo Go ilə 'My Tasks' ekranını real telefonda aç; mağazada yayımlama lazım deyil. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\nPulsuz Expo Go ilə 'My Tasks' ekranını real telefonda aç; mağazada yayımlama lazım deyil.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nTelefonda və ya emulatorda açıla bilən sadə mobil tətbiq yaradacaqsan. Layihəni sıfırdan qurub işə salma qaydasını sənədləşdirəcəksən.\n\n## 2. Başlamazdan əvvəl\nJavaScript-ə ilkin bələdlik, Node.js/npm, VS Code və terminaldan istifadə. Telefonda Expo Go istifadə edə bilərsən; Android emulatoru üçün Android Studio lazım ola bilər.\n\n## 3. Addım-addım icra\n1. GitHub-da özünə boş `mobile-starter-app` repo-su yarat. Sıfırdan başla.\n2. Node.js LTS və VS Code quraşdırıldığını yoxla.\n3. Terminalda `npx create-expo-app@latest mobile-starter-app --template blank-typescript` əmrini işlət və layihə qovluğuna keç.\n4. `npx expo start` ilə tətbiqi başlat. QR kodu Expo Go ilə oxut və ya emulator aç.\n5. Başlanğıc ekranda tətbiqin adını və “Salam!” mesajını göstər.\n6. `README.md`-də quraşdırma və işə salma addımlarını yaz. Gizli açar və parol əlavə etmə.\n7. Layihəni öz GitHub repo-na göndər və tətbiqin açıldığını göstərən screenshot əlavə et.\n\n## 4. Konkret nümunə və izah\nLayihəni yaratdıqdan sonra terminalda `cd mobile-starter-app`, sonra `npx expo start` işlət. Eyni adlı repo-nu əvvəl klonlamısansa, ikinci eyniadlı qovluq yaratmadığını yoxla. Telefon və development server eyni uyğun şəbəkədə olmalıdır.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işləyən Expo/TypeScript tətbiqi, quraşdırma təlimatlı README və tətbiqin açıldığını göstərən screenshot.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nTelefon/emulator tətbiqi açır və dəyişdirdiyin başlıq görünür. README-də qovluq, quraşdırma, start əmri və sınanmış cihaz/mühit qeyd edilib.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Open a My Tasks screen on a real phone using free Expo Go without app-store publishing.\n\n## Free tools and platforms — how to use them\n- **Node.js (free)** — https://nodejs.org. Install a local JavaScript/TypeScript runtime and run your development server.\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. Run a local React Native demo with Expo Go; paid store publishing or EAS is not required.\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / mobile-development / task-1` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Install Node.js and start a local Expo project. Show evidence in a real screen, prototype, source file or test.\n4. Open the sample app via Expo Go and display one basic screen. Show evidence in a real screen, prototype, source file or test.\n5. Document device/setup steps without requiring paid EAS builds. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Open a My Tasks screen on a real phone using free Expo Go without app-store publishing. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nOpen a My Tasks screen on a real phone using free Expo Go without app-store publishing.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nCreate a simple mobile app that opens on a phone or emulator. Set it up from scratch and document how to run it.\n\n## 2. Before you start\nIntroductory JavaScript, Node.js/npm, and basic VS Code and terminal use. Expo Go works on a phone; Android Studio may be needed for an emulator.\n\n## 3. Step-by-step work\n1. Create your own empty GitHub repository named `mobile-starter-app`. Start from scratch.\n2. Check that Node.js LTS and VS Code are installed.\n3. Run `npx create-expo-app@latest mobile-starter-app --template blank-typescript` in the terminal and enter the project folder.\n4. Start the app with `npx expo start`. Scan the QR code with Expo Go or open an emulator.\n5. Show the app name and a “Hello!” message on the home screen.\n6. Document setup and startup in `README.md`. Do not add secrets or passwords.\n7. Push the project to your own GitHub repository and add a screenshot showing the app running.\n\n## 4. Concrete example and explanation\nAfter creating the project run `cd mobile-starter-app`, then `npx expo start`. Avoid nesting a second folder with the same name if you already cloned the repository. The phone must reach the development server.\n\n## 5. What to submit\nYour own GitHub repository link, working Expo/TypeScript app, setup README, and a screenshot of the running app.\n\n## 6. How to check your work\nThe app opens on a phone/emulator and shows your edited title. Document folder, install/start commands, and tested device/environment."},{"slug":"mobile-development","task_number":2,"title":"Navigation Flow","old_description":"[[AZ]]\nTəcrübə dashboard-unda əsas ekranlar arasında geri düyməsi və deep-link-i nəzərə alan navigation qur.\n\n[[EN]]\nBuild app navigation for internship screens, accounting for back behavior and deep links.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nMobil tətbiqdə ekranlar arasında aydın naviqasiya quracaqsan ki, istifadəçi tapşırıq siyahısından detal və təqdimetmə ekranına keçə bilsin.\n\n## 2. Başlamazdan əvvəl\nTapşırıq 1-dəki öz Expo layihən, React Native View/Text/Button əsasları və sadə state. Expo Go və ya emulator istifadə et.\n\n## 3. Addım-addım icra\n1. Öz Tapşırıq 1 mobil repo-nu davam etdir.\n2. Home, task list, task detail və submit ekranları yarat.\n3. React Navigation və ya Expo Router-dan layihənə uyğun olanı seç; quraşdırma təlimatını izlə.\n4. Hər ekrana aydın başlıq və geri qayıtma yolu əlavə et.\n5. Tab/stack keçidlərini cihazda və ya emulatorda yoxla.\n6. README-də run addımlarını və naviqasiya qərarlarını yaz.\n\n## 4. Konkret nümunə və izah\nBir sintetik tapşırıq üçün ID=demo-1 götür. Siyahıdan həmin ID ilə detail-ə, oradan submit-ə keç; geri düyməsi əvvəlki ekrana qaytarsın. Eyni layihədə həm React Navigation, həm Expo Router qurmaq məcburi deyil.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işləyən ekran keçidləri, ən azı 4 ekran screenshot-u və README. Geri düyməsi və əsas keçidlər ilişmədən işləməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nDörd ekran açılır və düzgün task ID ötürülür. İrəli/geri keçidlər və olmayan ID üçün izahlı ekran cihazda sınanıb.\n\n[[EN]]\n## 1. Goal\nBuild clear navigation so a user can move from a task list to details and submission screens.\n\n## 2. Before you start\nYour own Expo project from Task 1, React Native View/Text/Button basics, and simple state. Use Expo Go or an emulator.\n\n## 3. Step-by-step work\n1. Continue your own mobile repository from Task 1.\n2. Create Home, task-list, task-detail, and submission screens.\n3. Choose React Navigation or Expo Router to fit your project and follow its setup instructions.\n4. Add a clear title and a way to go back on each screen.\n5. Test stack/tab navigation on a device or emulator.\n6. Document startup steps and navigation decisions in the README.\n\n## 4. Concrete example and explanation\nUse a fictional task ID demo-1. Navigate list → detail with that ID → submit; Back returns to the previous screen. Choose one navigation approach rather than installing both.\n\n## 5. What to submit\nYour own GitHub repository link, working screen navigation, screenshots of at least four screens, and README. Back navigation and primary transitions must work reliably.\n\n## 6. How to check your work\nOpen all four screens with the correct task ID. Test forward/back navigation and a clear missing-ID state on a device.","new_description":"[[AZ]]\nTəcrübə dashboard-unda əsas ekranlar arasında geri düyməsi və deep-link-i nəzərə alan navigation qur.\n\nPulsuz alətlər: Node.js (free), Expo Go / Expo CLI (free local), Visual Studio Code. Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nBuild app navigation for internship screens, accounting for back behavior and deep links.\n\nFree tools: Node.js (free), Expo Go / Expo CLI (free local), Visual Studio Code. The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** Tapşırıq siyahısı → detal → təqdim etmə ekranı arasında geri düyməsi düzgün işləsin.\n\n## Pulsuz platformalar və istifadə qaydası\n- **Node.js (free)** — https://nodejs.org. Lokal JavaScript/TypeScript mühiti qur, paketləri quraşdır və development server aç.\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. `npx expo start` ilə lokal React Native demo aç, Expo Go-da test et; app-store/EAS ödənişi lazım deyil.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / mobile-development / task-2` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. Expo Router və ya React Navigation ilə 3 ekranı qeydiyyatdan keçir. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. Tapşırıq ID-sini yalnız uyğun parametrlə növbəti ekrana ötür. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. Naməlum ID, geri və deep-link halını lokal sına. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: Tapşırıq siyahısı → detal → təqdim etmə ekranı arasında geri düyməsi düzgün işləsin. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\nTapşırıq siyahısı → detal → təqdim etmə ekranı arasında geri düyməsi düzgün işləsin.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nMobil tətbiqdə ekranlar arasında aydın naviqasiya quracaqsan ki, istifadəçi tapşırıq siyahısından detal və təqdimetmə ekranına keçə bilsin.\n\n## 2. Başlamazdan əvvəl\nTapşırıq 1-dəki öz Expo layihən, React Native View/Text/Button əsasları və sadə state. Expo Go və ya emulator istifadə et.\n\n## 3. Addım-addım icra\n1. Öz Tapşırıq 1 mobil repo-nu davam etdir.\n2. Home, task list, task detail və submit ekranları yarat.\n3. React Navigation və ya Expo Router-dan layihənə uyğun olanı seç; quraşdırma təlimatını izlə.\n4. Hər ekrana aydın başlıq və geri qayıtma yolu əlavə et.\n5. Tab/stack keçidlərini cihazda və ya emulatorda yoxla.\n6. README-də run addımlarını və naviqasiya qərarlarını yaz.\n\n## 4. Konkret nümunə və izah\nBir sintetik tapşırıq üçün ID=demo-1 götür. Siyahıdan həmin ID ilə detail-ə, oradan submit-ə keç; geri düyməsi əvvəlki ekrana qaytarsın. Eyni layihədə həm React Navigation, həm Expo Router qurmaq məcburi deyil.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işləyən ekran keçidləri, ən azı 4 ekran screenshot-u və README. Geri düyməsi və əsas keçidlər ilişmədən işləməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nDörd ekran açılır və düzgün task ID ötürülür. İrəli/geri keçidlər və olmayan ID üçün izahlı ekran cihazda sınanıb.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Implement list → task detail → submission navigation with correct back behavior.\n\n## Free tools and platforms — how to use them\n- **Node.js (free)** — https://nodejs.org. Install a local JavaScript/TypeScript runtime and run your development server.\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. Run a local React Native demo with Expo Go; paid store publishing or EAS is not required.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / mobile-development / task-2` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Register three screens using Expo Router or React Navigation. Show evidence in a real screen, prototype, source file or test.\n4. Pass a task ID through typed navigation parameters. Show evidence in a real screen, prototype, source file or test.\n5. Test unknown IDs, back navigation and basic deep linking. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Implement list → task detail → submission navigation with correct back behavior. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nImplement list → task detail → submission navigation with correct back behavior.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nBuild clear navigation so a user can move from a task list to details and submission screens.\n\n## 2. Before you start\nYour own Expo project from Task 1, React Native View/Text/Button basics, and simple state. Use Expo Go or an emulator.\n\n## 3. Step-by-step work\n1. Continue your own mobile repository from Task 1.\n2. Create Home, task-list, task-detail, and submission screens.\n3. Choose React Navigation or Expo Router to fit your project and follow its setup instructions.\n4. Add a clear title and a way to go back on each screen.\n5. Test stack/tab navigation on a device or emulator.\n6. Document startup steps and navigation decisions in the README.\n\n## 4. Concrete example and explanation\nUse a fictional task ID demo-1. Navigate list → detail with that ID → submit; Back returns to the previous screen. Choose one navigation approach rather than installing both.\n\n## 5. What to submit\nYour own GitHub repository link, working screen navigation, screenshots of at least four screens, and README. Back navigation and primary transitions must work reliably.\n\n## 6. How to check your work\nOpen all four screens with the correct task ID. Test forward/back navigation and a clear missing-ID state on a device."},{"slug":"mobile-development","task_number":3,"title":"Reusable Mobile Components","old_description":"[[AZ]]\nTask card, status badge və form sahələrini mobil ekranda təkrar istifadə edilən komponentlərə ayır.\n\n[[EN]]\nCreate reusable mobile components for task cards, status badges, and form fields.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nMobil tətbiqdə təkrar istifadə edilən komponentlər yaradaraq ekranların eyni üslubda görünməsini təmin edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz mobil repo-n, React Native component və props anlayışları. Mövcud dizaynına uyğun düymə, status nişanı və boş vəziyyət komponentləri hazırla.\n\n## 3. Addım-addım icra\n1. Öz Tapşırıq 1–2 layihəni davam etdir.\n2. Button, StatusBadge və EmptyState komponentləri yarat.\n3. Props ilə mətn, status, disabled və variantları idarə et.\n4. Rəng və spacing dəyərlərini mərkəzləşdir.\n5. Komponentləri ən azı iki ekranda istifadə et.\n6. Normal/disabled/empty variantlarının screenshot-larını çək və README-ni yenilə.\n\n## 4. Konkret nümunə və izah\nButton mətni və disabled seçimini props-dan alsın; StatusBadge “Gözləyir/Tamamlanıb” kimi mətni statusla göstərsin; EmptyState siyahı boş olanda səbəb və növbəti addımı bildirsin. Eyni komponenti iki ekranda təkrar istifadə et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, 3 reusable component, ən azı iki ekran istifadəsi və screenshot-lar. Komponentlərin görünüşü və davranışı ardıcıl olmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nÜç komponent ayrı fayllardadır, ən azı iki ekranda istifadə olunur. Disabled düymə klik qəbul etmir; status təkcə rənglə göstərilmir.\n\n[[EN]]\n## 1. Goal\nCreate reusable mobile components so screens share a consistent style.\n\n## 2. Before you start\nYour own mobile repository and React Native components/props. Build button, status badge, and empty-state components that fit your design.\n\n## 3. Step-by-step work\n1. Continue your own project from Tasks 1–2.\n2. Create Button, StatusBadge, and EmptyState components.\n3. Use props to control text, status, disabled state, and variants.\n4. Centralize color and spacing values.\n5. Reuse the components on at least two screens.\n6. Capture screenshots of normal/disabled/empty variants and update the README.\n\n## 4. Concrete example and explanation\nPass button text and disabled state as props. StatusBadge includes text such as Pending/Completed. EmptyState explains an empty list and next action. Reuse components on two screens.\n\n## 5. What to submit\nYour own GitHub repository link, three reusable components, use on at least two screens, and screenshots. Components must behave and look consistently.\n\n## 6. How to check your work\nKeep three components in separate files and reuse them on two screens. Disabled buttons do not fire; status is not color-only.","new_description":"[[AZ]]\nTask card, status badge və form sahələrini mobil ekranda təkrar istifadə edilən komponentlərə ayır.\n\nPulsuz alətlər: Node.js (free), Expo Go / Expo CLI (free local), Visual Studio Code. Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nCreate reusable mobile components for task cards, status badges, and form fields.\n\nFree tools: Node.js (free), Expo Go / Expo CLI (free local), Visual Studio Code. The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** TaskCard, StatusBadge və FormField mobil komponentlərini 320px ekranda sınayıb reuse et.\n\n## Pulsuz platformalar və istifadə qaydası\n- **Node.js (free)** — https://nodejs.org. Lokal JavaScript/TypeScript mühiti qur, paketləri quraşdır və development server aç.\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. `npx expo start` ilə lokal React Native demo aç, Expo Go-da test et; app-store/EAS ödənişi lazım deyil.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / mobile-development / task-3` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. Props və fərqli status variantlarını TypeScript ilə yaz. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. Eyni TaskCard komponentini iki siyahıda istifadə et. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. Mətn daşması, touch target və ekran oxuyucu label-lərini yoxla. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: TaskCard, StatusBadge və FormField mobil komponentlərini 320px ekranda sınayıb reuse et. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\nTaskCard, StatusBadge və FormField mobil komponentlərini 320px ekranda sınayıb reuse et.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nMobil tətbiqdə təkrar istifadə edilən komponentlər yaradaraq ekranların eyni üslubda görünməsini təmin edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz mobil repo-n, React Native component və props anlayışları. Mövcud dizaynına uyğun düymə, status nişanı və boş vəziyyət komponentləri hazırla.\n\n## 3. Addım-addım icra\n1. Öz Tapşırıq 1–2 layihəni davam etdir.\n2. Button, StatusBadge və EmptyState komponentləri yarat.\n3. Props ilə mətn, status, disabled və variantları idarə et.\n4. Rəng və spacing dəyərlərini mərkəzləşdir.\n5. Komponentləri ən azı iki ekranda istifadə et.\n6. Normal/disabled/empty variantlarının screenshot-larını çək və README-ni yenilə.\n\n## 4. Konkret nümunə və izah\nButton mətni və disabled seçimini props-dan alsın; StatusBadge “Gözləyir/Tamamlanıb” kimi mətni statusla göstərsin; EmptyState siyahı boş olanda səbəb və növbəti addımı bildirsin. Eyni komponenti iki ekranda təkrar istifadə et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, 3 reusable component, ən azı iki ekran istifadəsi və screenshot-lar. Komponentlərin görünüşü və davranışı ardıcıl olmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nÜç komponent ayrı fayllardadır, ən azı iki ekranda istifadə olunur. Disabled düymə klik qəbul etmir; status təkcə rənglə göstərilmir.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Create reusable TaskCard, StatusBadge and FormField components tested on a narrow phone.\n\n## Free tools and platforms — how to use them\n- **Node.js (free)** — https://nodejs.org. Install a local JavaScript/TypeScript runtime and run your development server.\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. Run a local React Native demo with Expo Go; paid store publishing or EAS is not required.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / mobile-development / task-3` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Type component props and variant states. Show evidence in a real screen, prototype, source file or test.\n4. Reuse the same TaskCard in two different lists. Show evidence in a real screen, prototype, source file or test.\n5. Check text overflow, touch targets and screen-reader labels. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Create reusable TaskCard, StatusBadge and FormField components tested on a narrow phone. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nCreate reusable TaskCard, StatusBadge and FormField components tested on a narrow phone.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nCreate reusable mobile components so screens share a consistent style.\n\n## 2. Before you start\nYour own mobile repository and React Native components/props. Build button, status badge, and empty-state components that fit your design.\n\n## 3. Step-by-step work\n1. Continue your own project from Tasks 1–2.\n2. Create Button, StatusBadge, and EmptyState components.\n3. Use props to control text, status, disabled state, and variants.\n4. Centralize color and spacing values.\n5. Reuse the components on at least two screens.\n6. Capture screenshots of normal/disabled/empty variants and update the README.\n\n## 4. Concrete example and explanation\nPass button text and disabled state as props. StatusBadge includes text such as Pending/Completed. EmptyState explains an empty list and next action. Reuse components on two screens.\n\n## 5. What to submit\nYour own GitHub repository link, three reusable components, use on at least two screens, and screenshots. Components must behave and look consistently.\n\n## 6. How to check your work\nKeep three components in separate files and reuse them on two screens. Disabled buttons do not fire; status is not color-only."},{"slug":"mobile-development","task_number":4,"title":"API Mobile List","old_description":"[[AZ]]\nAPI-dən tapşırıqları çəkən mobil siyahıda loading, refresh, empty və network error vəziyyətlərini qur.\n\n[[EN]]\nBuild a mobile task list backed by an API with loading, refresh, empty, and network-error states.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nTapşırıq siyahısını mock API-dən yükləyəcək və loading, empty, success və error vəziyyətlərini mobil ekranda göstərəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz mobil layihən, async/await, JSON və React Native list komponentləri. Real API açarı tələb olunmayan mock data ilə başla.\n\n## 3. Addım-addım icra\n1. Öz əvvəlki mobil repo-nu davam etdir.\n2. Task üçün TypeScript type və sintetik JSON data hazırla.\n3. Siyahını FlatList ilə göstər.\n4. Loading, empty, error və retry vəziyyətləri əlavə et.\n5. Yavaş cavab və şəbəkə xətasını mock et; retry dublikat sorğu yaratmasın.\n6. Hər vəziyyət üçün test və screenshot əlavə et.\n\n## 4. Konkret nümunə və izah\nMock cavabda `[{\"id\":\"demo-1\",\"title\":\"İlk tapşırıq\"}]` göstər; boş variant `[]` olsun. Gecikməni simulyasiya edib loading-i göstər. 500 xətasında boş siyahı deyil, xəta və “Yenidən cəhd et” düyməsi göstər.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işləyən API list ekranı, mock adapter, dörd vəziyyətin screenshot-u və testlər. Boş nəticə ilə xəta fərqli izah olunmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nLoading, success, empty və error ayrıca görünür. FlatList üçün sabit ID açarı var; retry zamanı paralel dublikat sorğu getmir.\n\n[[EN]]\n## 1. Goal\nLoad a task list from a mock API and show loading, empty, success, and error states on mobile.\n\n## 2. Before you start\nYour own mobile project, async/await, JSON, and React Native list components. Start with mock data that needs no real API key.\n\n## 3. Step-by-step work\n1. Continue your own mobile repository.\n2. Define a TypeScript task type and synthetic JSON data.\n3. Render the list with FlatList.\n4. Add loading, empty, error, and retry states.\n5. Mock slow responses and network failures; retry must not create duplicate requests.\n6. Add tests and screenshots for each state.\n\n## 4. Concrete example and explanation\nUse a mock response such as `[{\"id\":\"demo-1\",\"title\":\"First task\"}]`, plus `[]` for empty. Simulate delay for loading. A 500 response shows an error/retry rather than an empty list.\n\n## 5. What to submit\nYour own GitHub repository link, working API-list screen, mock adapter, screenshots of four states, and tests. Empty results and errors must be explained differently.\n\n## 6. How to check your work\nShow loading, success, empty, and error separately. FlatList uses stable ID keys and retry cannot create duplicate pending requests.","new_description":"[[AZ]]\nAPI-dən tapşırıqları çəkən mobil siyahıda loading, refresh, empty və network error vəziyyətlərini qur.\n\nPulsuz alətlər: Node.js (free), Expo Go / Expo CLI (free local), Visual Studio Code. Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nBuild a mobile task list backed by an API with loading, refresh, empty, and network-error states.\n\nFree tools: Node.js (free), Expo Go / Expo CLI (free local), Visual Studio Code. The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** Mock JSON-dan 5 tapşırıq yüklə; loading, pull-to-refresh, boş və offline xəta halını göstər.\n\n## Pulsuz platformalar və istifadə qaydası\n- **Node.js (free)** — https://nodejs.org. Lokal JavaScript/TypeScript mühiti qur, paketləri quraşdır və development server aç.\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. `npx expo start` ilə lokal React Native demo aç, Expo Go-da test et; app-store/EAS ödənişi lazım deyil.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / mobile-development / task-4` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. Lokal fixture və async mock fetch yarat. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. Dörd UI vəziyyətinin hər birini ayrıca göstər. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. Yenidən cəhd/pull-to-refresh davranışını video və ya ekran görüntüsü ilə sübut et. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: Mock JSON-dan 5 tapşırıq yüklə; loading, pull-to-refresh, boş və offline xəta halını göstər. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\nMock JSON-dan 5 tapşırıq yüklə; loading, pull-to-refresh, boş və offline xəta halını göstər.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nTapşırıq siyahısını mock API-dən yükləyəcək və loading, empty, success və error vəziyyətlərini mobil ekranda göstərəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz mobil layihən, async/await, JSON və React Native list komponentləri. Real API açarı tələb olunmayan mock data ilə başla.\n\n## 3. Addım-addım icra\n1. Öz əvvəlki mobil repo-nu davam etdir.\n2. Task üçün TypeScript type və sintetik JSON data hazırla.\n3. Siyahını FlatList ilə göstər.\n4. Loading, empty, error və retry vəziyyətləri əlavə et.\n5. Yavaş cavab və şəbəkə xətasını mock et; retry dublikat sorğu yaratmasın.\n6. Hər vəziyyət üçün test və screenshot əlavə et.\n\n## 4. Konkret nümunə və izah\nMock cavabda `[{\"id\":\"demo-1\",\"title\":\"İlk tapşırıq\"}]` göstər; boş variant `[]` olsun. Gecikməni simulyasiya edib loading-i göstər. 500 xətasında boş siyahı deyil, xəta və “Yenidən cəhd et” düyməsi göstər.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işləyən API list ekranı, mock adapter, dörd vəziyyətin screenshot-u və testlər. Boş nəticə ilə xəta fərqli izah olunmalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nLoading, success, empty və error ayrıca görünür. FlatList üçün sabit ID açarı var; retry zamanı paralel dublikat sorğu getmir.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Load five fictional tasks from a JSON fixture and handle loading, refresh, empty and error states.\n\n## Free tools and platforms — how to use them\n- **Node.js (free)** — https://nodejs.org. Install a local JavaScript/TypeScript runtime and run your development server.\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. Run a local React Native demo with Expo Go; paid store publishing or EAS is not required.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / mobile-development / task-4` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Prepare a local JSON fixture and async mock fetch. Show evidence in a real screen, prototype, source file or test.\n4. Implement loading, success, empty and error UI states. Show evidence in a real screen, prototype, source file or test.\n5. Demonstrate retry/pull-to-refresh with screenshots. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Load five fictional tasks from a JSON fixture and handle loading, refresh, empty and error states. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nLoad five fictional tasks from a JSON fixture and handle loading, refresh, empty and error states.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nLoad a task list from a mock API and show loading, empty, success, and error states on mobile.\n\n## 2. Before you start\nYour own mobile project, async/await, JSON, and React Native list components. Start with mock data that needs no real API key.\n\n## 3. Step-by-step work\n1. Continue your own mobile repository.\n2. Define a TypeScript task type and synthetic JSON data.\n3. Render the list with FlatList.\n4. Add loading, empty, error, and retry states.\n5. Mock slow responses and network failures; retry must not create duplicate requests.\n6. Add tests and screenshots for each state.\n\n## 4. Concrete example and explanation\nUse a mock response such as `[{\"id\":\"demo-1\",\"title\":\"First task\"}]`, plus `[]` for empty. Simulate delay for loading. A 500 response shows an error/retry rather than an empty list.\n\n## 5. What to submit\nYour own GitHub repository link, working API-list screen, mock adapter, screenshots of four states, and tests. Empty results and errors must be explained differently.\n\n## 6. How to check your work\nShow loading, success, empty, and error separately. FlatList uses stable ID keys and retry cannot create duplicate pending requests."},{"slug":"mobile-development","task_number":5,"title":"Search and Filter","old_description":"[[AZ]]\nTapşırıq siyahısına status filter-i və yerli axtarış əlavə et, filter dəyişməsini aydın göstər.\n\n[[EN]]\nAdd status filters and local search to the task list with clear filter-state feedback.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nMobil task siyahısına axtarış və status filter-i əlavə edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz əvvəlki mobil layihən, React state, input və list filter əsasları.\n\n## 3. Addım-addım icra\n1. Öz mobil repo-nu davam etdir.\n2. Search input və status filter əlavə et.\n3. Filter-ləri birlikdə tətbiq et və nəticə yoxdursa empty state göstər.\n4. Klaviatura açıq olanda nəticə siyahısının istifadəsini yoxla.\n5. Böyük sintetik siyahı ilə performansı yoxla.\n6. Axtarış, filter və boş nəticə üçün test yaz.\n\n## 4. Konkret nümunə və izah\n“Təqdimat” sözünü axtarıb yalnız “Gözləyir” statusunu seçəndə hər iki şərtə uyğun nəticələr qalsın. Axtarış boşaldıldıqda status filtri itməsin. Böyük siyahı üçün ən azı 200 sintetik qeyd istifadə et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, axtarış/filter funksiyası, testlər və screenshot-lar. Filter dəyişdikdə nəticələr düzgün yenilənməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nAxtarış, filtr, birlikdə tətbiq və sıfırlama sınaqları var. Klaviatura açıq olanda nəticə və əsas düymələr əlçatan qalır.\n\n[[EN]]\n## 1. Goal\nAdd search and status filtering to the mobile task list.\n\n## 2. Before you start\nYour existing mobile project, React state, inputs, and basic list filtering.\n\n## 3. Step-by-step work\n1. Continue your own mobile repository.\n2. Add a search input and status filter.\n3. Combine filters and show an empty state when nothing matches.\n4. Check that the list remains usable while the keyboard is open.\n5. Check performance with a larger synthetic list.\n6. Test search, filtering, and empty results.\n\n## 4. Concrete example and explanation\nSearching for “Presentation” with Pending selected returns records matching both. Clearing search preserves the status filter. Use at least 200 synthetic records for the larger-list check.\n\n## 5. What to submit\nYour own GitHub repository link, search/filter feature, tests, and screenshots. Results must update correctly when filters change.\n\n## 6. How to check your work\nTest search, filter, combined conditions, and reset. Results and primary actions remain reachable with the keyboard open.","new_description":"[[AZ]]\nTapşırıq siyahısına status filter-i və yerli axtarış əlavə et, filter dəyişməsini aydın göstər.\n\nPulsuz alətlər: Node.js (free), Expo Go / Expo CLI (free local), Visual Studio Code. Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nAdd status filters and local search to the task list with clear filter-state feedback.\n\nFree tools: Node.js (free), Expo Go / Expo CLI (free local), Visual Studio Code. The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** 'pending' statuslu tapşırıqları filter-lə və başlıqda 'API' yazısını axtar.\n\n## Pulsuz platformalar və istifadə qaydası\n- **Node.js (free)** — https://nodejs.org. Lokal JavaScript/TypeScript mühiti qur, paketləri quraşdır və development server aç.\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. `npx expo start` ilə lokal React Native demo aç, Expo Go-da test et; app-store/EAS ödənişi lazım deyil.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / mobile-development / task-5` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. Search input və status chip-lərini state-ə bağla. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. Axtarış və status filtrinin eyni vaxtda işləməsini göstər. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. Nəticə boşdursa izah mesajı və 'Filtri təmizlə' düyməsi göstər. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: 'pending' statuslu tapşırıqları filter-lə və başlıqda 'API' yazısını axtar. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\n'pending' statuslu tapşırıqları filter-lə və başlıqda 'API' yazısını axtar.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nMobil task siyahısına axtarış və status filter-i əlavə edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz əvvəlki mobil layihən, React state, input və list filter əsasları.\n\n## 3. Addım-addım icra\n1. Öz mobil repo-nu davam etdir.\n2. Search input və status filter əlavə et.\n3. Filter-ləri birlikdə tətbiq et və nəticə yoxdursa empty state göstər.\n4. Klaviatura açıq olanda nəticə siyahısının istifadəsini yoxla.\n5. Böyük sintetik siyahı ilə performansı yoxla.\n6. Axtarış, filter və boş nəticə üçün test yaz.\n\n## 4. Konkret nümunə və izah\n“Təqdimat” sözünü axtarıb yalnız “Gözləyir” statusunu seçəndə hər iki şərtə uyğun nəticələr qalsın. Axtarış boşaldıldıqda status filtri itməsin. Böyük siyahı üçün ən azı 200 sintetik qeyd istifadə et.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, axtarış/filter funksiyası, testlər və screenshot-lar. Filter dəyişdikdə nəticələr düzgün yenilənməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nAxtarış, filtr, birlikdə tətbiq və sıfırlama sınaqları var. Klaviatura açıq olanda nəticə və əsas düymələr əlçatan qalır.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Filter pending tasks and search titles for a sample query such as 'API'.\n\n## Free tools and platforms — how to use them\n- **Node.js (free)** — https://nodejs.org. Install a local JavaScript/TypeScript runtime and run your development server.\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. Run a local React Native demo with Expo Go; paid store publishing or EAS is not required.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / mobile-development / task-5` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Connect search input and status chips to local state. Show evidence in a real screen, prototype, source file or test.\n4. Demonstrate combined search and status filtering. Show evidence in a real screen, prototype, source file or test.\n5. Display a meaningful empty state and clear-filters action. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Filter pending tasks and search titles for a sample query such as 'API'. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nFilter pending tasks and search titles for a sample query such as 'API'.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nAdd search and status filtering to the mobile task list.\n\n## 2. Before you start\nYour existing mobile project, React state, inputs, and basic list filtering.\n\n## 3. Step-by-step work\n1. Continue your own mobile repository.\n2. Add a search input and status filter.\n3. Combine filters and show an empty state when nothing matches.\n4. Check that the list remains usable while the keyboard is open.\n5. Check performance with a larger synthetic list.\n6. Test search, filtering, and empty results.\n\n## 4. Concrete example and explanation\nSearching for “Presentation” with Pending selected returns records matching both. Clearing search preserves the status filter. Use at least 200 synthetic records for the larger-list check.\n\n## 5. What to submit\nYour own GitHub repository link, search/filter feature, tests, and screenshots. Results must update correctly when filters change.\n\n## 6. How to check your work\nTest search, filter, combined conditions, and reset. Results and primary actions remain reachable with the keyboard open."},{"slug":"mobile-development","task_number":6,"title":"Local Storage","old_description":"[[AZ]]\nİstifadəçi seçimini yalnız həssas olmayan məlumatlar üçün lokal storage-da saxla və migration qərarını yaz.\n\n[[EN]]\nPersist non-sensitive user preferences locally and document the storage/migration choice.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nİstifadəçinin seçdiyi sadə parametri tətbiq bağlanıb açılandan sonra da saxlamağı öyrənəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz mobil layihən, async storage anlayışı və state lifecycle. Token, parol və digər həssas məlumatı sadə local storage-da saxlama.\n\n## 3. Addım-addım icra\n1. Öz mobil repo-nu davam etdir.\n2. Saxlanacaq həssas olmayan seçim seç, məsələn, tema və ya son filter.\n3. AsyncStorage və ya layihənin uyğun storage həllindən istifadə et.\n4. İlk açılışda default dəyər, saxlanmış dəyər və storage xətası hallarını idarə et.\n5. Tətbiqi bağlayıb açaraq dəyərin bərpa olunduğunu yoxla.\n6. Storage davranışı üçün test və README qeydi əlavə et.\n\n## 4. Konkret nümunə və izah\nMəsələn, seçilmiş statusu `selectedStatus` açarı ilə saxla. İlk açılışda dəyər yoxdursa “Bütün tapşırıqlar” seçilsin; saxlama uğursuz olsa tətbiq işləməyə davam etsin. Yeni başlanğıc dəyəri əvvəlki saxlanmış seçimi oxunmadan əvəz etməsin.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, persistence implementasiyası, testlər və screenshot/demo. Həssas məlumat saxlanmamalı, storage xətası tətbiqi çökdürməməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nTətbiqi tam bağlayıb açanda seçim qayıdır. Dəyərsiz, korlanmış dəyər və storage xətası yoxlanılıb; heç bir parol/token burada saxlanmır.\n\n[[EN]]\n## 1. Goal\nPersist a simple user preference after the app closes and reopens.\n\n## 2. Before you start\nYour own mobile project, async storage, and state lifecycle. Do not store passwords, tokens, or other sensitive data in simple local storage.\n\n## 3. Step-by-step work\n1. Continue your own mobile repository.\n2. Choose a non-sensitive preference such as theme or last-used filter.\n3. Use AsyncStorage or an appropriate storage solution for the project.\n4. Handle first launch, saved values, and storage errors.\n5. Close and reopen the app to confirm the value is restored.\n6. Add a test and document storage behavior in the README.\n\n## 4. Concrete example and explanation\nPersist the selected status under a key such as `selectedStatus`. Default to All tasks when absent and keep the app usable on storage failure. Do not overwrite saved preferences before loading them.\n\n## 5. What to submit\nYour own GitHub repository link, persistence implementation, tests, and screenshot/demo. Do not store sensitive data, and storage errors must not crash the app.\n\n## 6. How to check your work\nFully close/reopen and restore the choice. Test absent/corrupt values and storage errors; store no passwords or tokens here.","new_description":"[[AZ]]\nİstifadəçi seçimini yalnız həssas olmayan məlumatlar üçün lokal storage-da saxla və migration qərarını yaz.\n\nPulsuz alətlər: Node.js (free), Expo Go / Expo CLI (free local), Visual Studio Code. Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nPersist non-sensitive user preferences locally and document the storage/migration choice.\n\nFree tools: Node.js (free), Expo Go / Expo CLI (free local), Visual Studio Code. The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** 'darkMode=true' kimi qeyri-həssas seçimi lokal saxla, tətbiq açıldıqda bərpa et.\n\n## Pulsuz platformalar və istifadə qaydası\n- **Node.js (free)** — https://nodejs.org. Lokal JavaScript/TypeScript mühiti qur, paketləri quraşdır və development server aç.\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. `npx expo start` ilə lokal React Native demo aç, Expo Go-da test et; app-store/EAS ödənişi lazım deyil.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / mobile-development / task-6` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. Yalnız tema və filtr seçimi kimi qeyri-həssas məlumat saxla. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. Lokal AsyncStorage ilə yazma/oxuma hallarını yoxla. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. Yanlış/boş saxlanmış dəyər üçün təhlükəsiz default göstər; token və şifrə saxlama. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: 'darkMode=true' kimi qeyri-həssas seçimi lokal saxla, tətbiq açıldıqda bərpa et. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\n'darkMode=true' kimi qeyri-həssas seçimi lokal saxla, tətbiq açıldıqda bərpa et.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nİstifadəçinin seçdiyi sadə parametri tətbiq bağlanıb açılandan sonra da saxlamağı öyrənəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz mobil layihən, async storage anlayışı və state lifecycle. Token, parol və digər həssas məlumatı sadə local storage-da saxlama.\n\n## 3. Addım-addım icra\n1. Öz mobil repo-nu davam etdir.\n2. Saxlanacaq həssas olmayan seçim seç, məsələn, tema və ya son filter.\n3. AsyncStorage və ya layihənin uyğun storage həllindən istifadə et.\n4. İlk açılışda default dəyər, saxlanmış dəyər və storage xətası hallarını idarə et.\n5. Tətbiqi bağlayıb açaraq dəyərin bərpa olunduğunu yoxla.\n6. Storage davranışı üçün test və README qeydi əlavə et.\n\n## 4. Konkret nümunə və izah\nMəsələn, seçilmiş statusu `selectedStatus` açarı ilə saxla. İlk açılışda dəyər yoxdursa “Bütün tapşırıqlar” seçilsin; saxlama uğursuz olsa tətbiq işləməyə davam etsin. Yeni başlanğıc dəyəri əvvəlki saxlanmış seçimi oxunmadan əvəz etməsin.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, persistence implementasiyası, testlər və screenshot/demo. Həssas məlumat saxlanmamalı, storage xətası tətbiqi çökdürməməlidir.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nTətbiqi tam bağlayıb açanda seçim qayıdır. Dəyərsiz, korlanmış dəyər və storage xətası yoxlanılıb; heç bir parol/token burada saxlanmır.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Persist a non-sensitive preference such as darkMode=true and restore it on relaunch.\n\n## Free tools and platforms — how to use them\n- **Node.js (free)** — https://nodejs.org. Install a local JavaScript/TypeScript runtime and run your development server.\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. Run a local React Native demo with Expo Go; paid store publishing or EAS is not required.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / mobile-development / task-6` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Store harmless preferences such as theme and filter settings only. Show evidence in a real screen, prototype, source file or test.\n4. Test writing/reading through local AsyncStorage. Show evidence in a real screen, prototype, source file or test.\n5. Use safe defaults and never store credentials in plain storage. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Persist a non-sensitive preference such as darkMode=true and restore it on relaunch. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nPersist a non-sensitive preference such as darkMode=true and restore it on relaunch.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nPersist a simple user preference after the app closes and reopens.\n\n## 2. Before you start\nYour own mobile project, async storage, and state lifecycle. Do not store passwords, tokens, or other sensitive data in simple local storage.\n\n## 3. Step-by-step work\n1. Continue your own mobile repository.\n2. Choose a non-sensitive preference such as theme or last-used filter.\n3. Use AsyncStorage or an appropriate storage solution for the project.\n4. Handle first launch, saved values, and storage errors.\n5. Close and reopen the app to confirm the value is restored.\n6. Add a test and document storage behavior in the README.\n\n## 4. Concrete example and explanation\nPersist the selected status under a key such as `selectedStatus`. Default to All tasks when absent and keep the app usable on storage failure. Do not overwrite saved preferences before loading them.\n\n## 5. What to submit\nYour own GitHub repository link, persistence implementation, tests, and screenshot/demo. Do not store sensitive data, and storage errors must not crash the app.\n\n## 6. How to check your work\nFully close/reopen and restore the choice. Test absent/corrupt values and storage errors; store no passwords or tokens here."},{"slug":"mobile-development","task_number":7,"title":"Form Validation","old_description":"[[AZ]]\nMüraciət formunda mobil klaviatura, field validation və submit zamanı səhv bərpasını həll et.\n\n[[EN]]\nHandle mobile keyboard behavior, field validation, and recovery from submission errors.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nMobil müraciət formuna aydın validation və istifadəçiyə kömək edən xəta mesajları əlavə edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz mobil repo-n, form input-ları, validation və async submit anlayışları.\n\n## 3. Addım-addım icra\n1. Öz layihəni davam etdir.\n2. Məcburi sahələri və uzunluq/format qaydalarını müəyyən et.\n3. Xətanı sahənin yanında göstər və focus-u uyğun sahəyə yönəlt.\n4. Submit zamanı loading/disabled və success/error vəziyyətlərini qur.\n5. Uğursuz submit-dən sonra daxil edilmiş məlumatı saxla.\n6. Valid, invalid, server error və double-submit ssenarilərini test et.\n\n## 4. Konkret nümunə və izah\nMotivasiya üçün 100–1000 simvol, optional portfolio üçün URL qaydası kimi konkret məhdudiyyətlər seç. Xətalı sahəyə izah əlavə et; kiçik ekranda klaviatura Göndər düyməsini örtəndə səhifə sürüşdürülə bilsin.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, form və validation qaydaları, ən azı 4 test ssenarisi və mobil screenshot. Xəta səbəbi aydın olmalı və double-submit dublikat yaratmamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nDüzgün giriş, yanlış giriş, server xətası və ikiqat klik sınaqları var. Uğursuz göndərmədən sonra mətn qalır; error sahəyə bağlı və oxunaqlıdır.\n\n[[EN]]\n## 1. Goal\nAdd clear validation and helpful error messages to a mobile application form.\n\n## 2. Before you start\nYour own mobile repository, form inputs, validation, and asynchronous submission.\n\n## 3. Step-by-step work\n1. Continue your own project.\n2. Define required fields and length/format rules.\n3. Show errors next to fields and move focus to the relevant field when appropriate.\n4. Add loading/disabled and success/error states during submission.\n5. Preserve entered values after a failed submission.\n6. Test valid input, invalid input, server errors, and double submission.\n\n## 4. Concrete example and explanation\nDefine concrete rules, such as 100–1000 motivation characters and a URL for optional portfolio. Explain field errors and allow scrolling when the keyboard covers Submit.\n\n## 5. What to submit\nYour own GitHub repository link, form and validation rules, at least four test scenarios, and a mobile screenshot. Errors must be clear and double submission must not create duplicates.\n\n## 6. How to check your work\nTest valid input, invalid input, server failure, and double-click. Failed submission retains text; errors are associated with readable field messages.","new_description":"[[AZ]]\nMüraciət formunda mobil klaviatura, field validation və submit zamanı səhv bərpasını həll et.\n\nPulsuz alətlər: Node.js (free), Expo Go / Expo CLI (free local), Visual Studio Code. Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nHandle mobile keyboard behavior, field validation, and recovery from submission errors.\n\nFree tools: Node.js (free), Expo Go / Expo CLI (free local), Visual Studio Code. The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** Email yanlış, portfel linki boş və klaviatura açıq olanda submit formunun vəziyyətini yoxla.\n\n## Pulsuz platformalar və istifadə qaydası\n- **Node.js (free)** — https://nodejs.org. Lokal JavaScript/TypeScript mühiti qur, paketləri quraşdır və development server aç.\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. `npx expo start` ilə lokal React Native demo aç, Expo Go-da test et; app-store/EAS ödənişi lazım deyil.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / mobile-development / task-7` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. Input qaydaları və error text-lərini yaz. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. Telefon klaviaturası açıldıqda submit düyməsinin görünməsini yoxla. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. Uğurlu/yanlış submit halını mock data ilə test et. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: Email yanlış, portfel linki boş və klaviatura açıq olanda submit formunun vəziyyətini yoxla. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\nEmail yanlış, portfel linki boş və klaviatura açıq olanda submit formunun vəziyyətini yoxla.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nMobil müraciət formuna aydın validation və istifadəçiyə kömək edən xəta mesajları əlavə edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz mobil repo-n, form input-ları, validation və async submit anlayışları.\n\n## 3. Addım-addım icra\n1. Öz layihəni davam etdir.\n2. Məcburi sahələri və uzunluq/format qaydalarını müəyyən et.\n3. Xətanı sahənin yanında göstər və focus-u uyğun sahəyə yönəlt.\n4. Submit zamanı loading/disabled və success/error vəziyyətlərini qur.\n5. Uğursuz submit-dən sonra daxil edilmiş məlumatı saxla.\n6. Valid, invalid, server error və double-submit ssenarilərini test et.\n\n## 4. Konkret nümunə və izah\nMotivasiya üçün 100–1000 simvol, optional portfolio üçün URL qaydası kimi konkret məhdudiyyətlər seç. Xətalı sahəyə izah əlavə et; kiçik ekranda klaviatura Göndər düyməsini örtəndə səhifə sürüşdürülə bilsin.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, form və validation qaydaları, ən azı 4 test ssenarisi və mobil screenshot. Xəta səbəbi aydın olmalı və double-submit dublikat yaratmamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nDüzgün giriş, yanlış giriş, server xətası və ikiqat klik sınaqları var. Uğursuz göndərmədən sonra mətn qalır; error sahəyə bağlı və oxunaqlıdır.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Validate email, empty portfolio link and keyboard interaction in a mobile form.\n\n## Free tools and platforms — how to use them\n- **Node.js (free)** — https://nodejs.org. Install a local JavaScript/TypeScript runtime and run your development server.\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. Run a local React Native demo with Expo Go; paid store publishing or EAS is not required.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / mobile-development / task-7` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Define input constraints and error messages. Show evidence in a real screen, prototype, source file or test.\n4. Check submit visibility while the keyboard is open. Show evidence in a real screen, prototype, source file or test.\n5. Test valid/invalid submissions using fictional data. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Validate email, empty portfolio link and keyboard interaction in a mobile form. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nValidate email, empty portfolio link and keyboard interaction in a mobile form.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nAdd clear validation and helpful error messages to a mobile application form.\n\n## 2. Before you start\nYour own mobile repository, form inputs, validation, and asynchronous submission.\n\n## 3. Step-by-step work\n1. Continue your own project.\n2. Define required fields and length/format rules.\n3. Show errors next to fields and move focus to the relevant field when appropriate.\n4. Add loading/disabled and success/error states during submission.\n5. Preserve entered values after a failed submission.\n6. Test valid input, invalid input, server errors, and double submission.\n\n## 4. Concrete example and explanation\nDefine concrete rules, such as 100–1000 motivation characters and a URL for optional portfolio. Explain field errors and allow scrolling when the keyboard covers Submit.\n\n## 5. What to submit\nYour own GitHub repository link, form and validation rules, at least four test scenarios, and a mobile screenshot. Errors must be clear and double submission must not create duplicates.\n\n## 6. How to check your work\nTest valid input, invalid input, server failure, and double-click. Failed submission retains text; errors are associated with readable field messages."},{"slug":"mobile-development","task_number":8,"title":"Offline State","old_description":"[[AZ]]\nŞəbəkə itəndə cache edilmiş tapşırıqları oxunaqlı saxla və sync vəziyyətini dürüst göstər.\n\n[[EN]]\nKeep cached tasks readable offline and report synchronization state honestly.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nŞəbəkə olmayanda tətbiqin davranışını aydın edəcək və son məlum məlumatı təhlükəsiz göstərəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz mobil layihən, API loading/error state-ləri və lokal cache əsasları. Həssas məlumatı cache etmə.\n\n## 3. Addım-addım icra\n1. Öz mobil repo-nu davam etdir.\n2. Şəbəkə statusunu və request xətasını ayırd et.\n3. Offline banner və retry action əlavə et.\n4. Əvvəldən yüklənmiş sintetik task siyahısını son məlum data kimi göstərə bilərsən; köhnə olduğunu işarələ.\n5. Offline → online keçidi, request timeout və cache boş vəziyyətini test et.\n6. README-də offline məhdudiyyətləri və data yenilənmə qaydasını yaz.\n\n## 4. Konkret nümunə və izah\nSon yüklənmiş sintetik siyahının yanında “Son yenilənmə: 14:30; internet yoxdur” yaz. Keş — əvvəlki cavabın lokal saxlanmış nüsxəsidir. İnternet olmayan ilk açılışda heç bir nüsxə yoxdursa ayrıca izah göstər.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, offline state UI, retry/cache davranışı, testlər və screenshot-lar. İstifadəçi şəbəkə olmayanda niyə məlumatın yenilənmədiyini anlamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nKeşli və keşsiz offline vəziyyət, timeout və yenidən online olma sınanıb. Köhnə məlumat yeni kimi göstərilmir; şəbəkə gələndə yeniləmə qaydası aydındır.\n\n[[EN]]\n## 1. Goal\nMake the app's behavior clear when there is no network and safely show the last known data when available.\n\n## 2. Before you start\nYour own mobile project, API loading/error states, and basic local caching. Do not cache sensitive data.\n\n## 3. Step-by-step work\n1. Continue your own mobile repository.\n2. Distinguish offline status from a request error.\n3. Add an offline banner and retry action.\n4. You may show a previously loaded synthetic task list as last-known data, clearly marked as potentially stale.\n5. Test offline-to-online recovery, request timeout, and an empty cache.\n6. Document offline limitations and refresh behavior in the README.\n\n## 4. Concrete example and explanation\nLabel cached fictional tasks “Last updated 14:30; offline”. A cache is a locally stored previous response. On a first launch without data or internet, show a separate no-cache explanation.\n\n## 5. What to submit\nYour own GitHub repository link, offline UI, retry/cache behavior, tests, and screenshots. Users must understand why data cannot be refreshed offline.\n\n## 6. How to check your work\nTest offline with/without cache, timeout, and reconnection. Never label stale data as current; explain refresh on reconnection.","new_description":"[[AZ]]\nŞəbəkə itəndə cache edilmiş tapşırıqları oxunaqlı saxla və sync vəziyyətini dürüst göstər.\n\nPulsuz alətlər: Node.js (free), Expo Go / Expo CLI (free local), Visual Studio Code. Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nKeep cached tasks readable offline and report synchronization state honestly.\n\nFree tools: Node.js (free), Expo Go / Expo CLI (free local), Visual Studio Code. The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** İnternet sönəndə son yüklənmiş 5 tapşırıq 'köhnə məlumat' etiketi ilə qalsın.\n\n## Pulsuz platformalar və istifadə qaydası\n- **Node.js (free)** — https://nodejs.org. Lokal JavaScript/TypeScript mühiti qur, paketləri quraşdır və development server aç.\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. `npx expo start` ilə lokal React Native demo aç, Expo Go-da test et; app-store/EAS ödənişi lazım deyil.\n- **Visual Studio Code** — https://code.visualstudio.com. Layihə qovluğunu aç, sintaksis xətalarını yoxla və faylları təşkil et.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / mobile-development / task-8` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. Son uğurlu mock fetch nəticəsini lokal saxlama qatına yaz. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. Offline zamanı `last_updated` tarixini və 'Yenilənməyib' mesajını göstər. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. Bağlantı qayıdanda refresh və data fərqini test et. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: İnternet sönəndə son yüklənmiş 5 tapşırıq 'köhnə məlumat' etiketi ilə qalsın. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\nİnternet sönəndə son yüklənmiş 5 tapşırıq 'köhnə məlumat' etiketi ilə qalsın.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nŞəbəkə olmayanda tətbiqin davranışını aydın edəcək və son məlum məlumatı təhlükəsiz göstərəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz mobil layihən, API loading/error state-ləri və lokal cache əsasları. Həssas məlumatı cache etmə.\n\n## 3. Addım-addım icra\n1. Öz mobil repo-nu davam etdir.\n2. Şəbəkə statusunu və request xətasını ayırd et.\n3. Offline banner və retry action əlavə et.\n4. Əvvəldən yüklənmiş sintetik task siyahısını son məlum data kimi göstərə bilərsən; köhnə olduğunu işarələ.\n5. Offline → online keçidi, request timeout və cache boş vəziyyətini test et.\n6. README-də offline məhdudiyyətləri və data yenilənmə qaydasını yaz.\n\n## 4. Konkret nümunə və izah\nSon yüklənmiş sintetik siyahının yanında “Son yenilənmə: 14:30; internet yoxdur” yaz. Keş — əvvəlki cavabın lokal saxlanmış nüsxəsidir. İnternet olmayan ilk açılışda heç bir nüsxə yoxdursa ayrıca izah göstər.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, offline state UI, retry/cache davranışı, testlər və screenshot-lar. İstifadəçi şəbəkə olmayanda niyə məlumatın yenilənmədiyini anlamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nKeşli və keşsiz offline vəziyyət, timeout və yenidən online olma sınanıb. Köhnə məlumat yeni kimi göstərilmir; şəbəkə gələndə yeniləmə qaydası aydındır.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Display cached fictional tasks with an explicit stale-data label when offline.\n\n## Free tools and platforms — how to use them\n- **Node.js (free)** — https://nodejs.org. Install a local JavaScript/TypeScript runtime and run your development server.\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. Run a local React Native demo with Expo Go; paid store publishing or EAS is not required.\n- **Visual Studio Code** — https://code.visualstudio.com. Open your project folder, inspect syntax and organize source files.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / mobile-development / task-8` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Cache the last successfully fetched fictional task list. Show evidence in a real screen, prototype, source file or test.\n4. Show last-updated time and an offline/stale label. Show evidence in a real screen, prototype, source file or test.\n5. Test refresh and synchronization when connectivity returns. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Display cached fictional tasks with an explicit stale-data label when offline. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nDisplay cached fictional tasks with an explicit stale-data label when offline.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nMake the app's behavior clear when there is no network and safely show the last known data when available.\n\n## 2. Before you start\nYour own mobile project, API loading/error states, and basic local caching. Do not cache sensitive data.\n\n## 3. Step-by-step work\n1. Continue your own mobile repository.\n2. Distinguish offline status from a request error.\n3. Add an offline banner and retry action.\n4. You may show a previously loaded synthetic task list as last-known data, clearly marked as potentially stale.\n5. Test offline-to-online recovery, request timeout, and an empty cache.\n6. Document offline limitations and refresh behavior in the README.\n\n## 4. Concrete example and explanation\nLabel cached fictional tasks “Last updated 14:30; offline”. A cache is a locally stored previous response. On a first launch without data or internet, show a separate no-cache explanation.\n\n## 5. What to submit\nYour own GitHub repository link, offline UI, retry/cache behavior, tests, and screenshots. Users must understand why data cannot be refreshed offline.\n\n## 6. How to check your work\nTest offline with/without cache, timeout, and reconnection. Never label stale data as current; explain refresh on reconnection."},{"slug":"mobile-development","task_number":9,"title":"Mobile UX Test","old_description":"[[AZ]]\nƏsas mobil istifadə axınını real cihaz ölçüləri, əlçatanlıq və performans baxımından yoxla.\n\n[[EN]]\nReview the main mobile flow for device sizes, accessibility, and performance.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nMobil tətbiqin əsas axınını real istifadəçilərlə yoxlayıb anlaşılmayan addımları tapacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz işlək prototip/tətbiqin, neytral test tapşırıqları və razılıq alma qaydası. Mümkünsə 3–5 iştirakçı ilə sına.\n\n## 3. Addım-addım icra\n1. Öz mobil layihəni davam etdir.\n2. Task tapmaq, detallara baxmaq və həll təqdim etmək üçün 3 test ssenarisi yaz.\n3. İştirakçıdan tətbiqi özünün istifadə etməsini istə; addımları izah edib cavabı yönləndirmə.\n4. Vaxt, səhv klik və kömək ehtiyacını anonim qeyd et.\n5. Ən azı 5 tapıntını təsirə görə sırala.\n6. Bir düzəliş et və retest nəticəsini qeyd et.\n\n## 4. Konkret nümunə və izah\nNeytral ssenari: “Dizayn tapşırığını tap və hansı linki təqdim etməli olduğunu müəyyən et”. İştirakçıya hansı düyməni basacağını demə. İştirakçı tapılmırsa, öz ekspert yoxlamanı ayrıca qeyd et; istifadəçi testi apardığını iddia etmə.\n\n## 5. Nə təhvil verməlisən?\nTest planı, iştirakçı sayı, anonim müşahidələr, 5+ tapıntı, düzəliş və retest sübutu. Razılıq olmadan qeyd aparma və lazımsız şəxsi məlumat toplama.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nİştirakçı sayı və razılıq üsulu, 3 ssenari, anonim müşahidələr, prioritetlər və bir düzəlişin təkrar yoxlaması var. Müşahidə ilə fərziyyə ayrılıb.\n\n[[EN]]\n## 1. Goal\nTest the mobile app's main flow with users and identify confusing steps.\n\n## 2. Before you start\nYour working prototype/app, neutral test tasks, and consent basics. Aim for three to five participants when possible.\n\n## 3. Step-by-step work\n1. Continue your own mobile project.\n2. Write three test scenarios: find a task, view details, and submit a solution.\n3. Ask participants to use the app themselves; do not guide their answers.\n4. Record time, misclicks, and requests for help anonymously.\n5. Rank at least five findings by impact.\n6. Make one improvement and record the retest result.\n\n## 4. Concrete example and explanation\nNeutral scenario: “Find the design task and determine which link to submit.” Do not tell participants which button to press. If no participant is available, label an expert walkthrough honestly.\n\n## 5. What to submit\nA test plan, participant count, anonymized observations, five or more findings, a fix, and retest evidence. Do not record without consent or collect unnecessary personal data.\n\n## 6. How to check your work\nReport participant count/consent, three scenarios, anonymous observations, priorities, and a retest of one fix. Separate observation from assumption.","new_description":"[[AZ]]\nƏsas mobil istifadə axınını real cihaz ölçüləri, əlçatanlıq və performans baxımından yoxla.\n\nPulsuz alətlər: Expo Go / Expo CLI (free local), Google Docs (personal). Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nReview the main mobile flow for device sizes, accessibility, and performance.\n\nFree tools: Expo Go / Expo CLI (free local), Google Docs (personal). The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** Bir istifadəçi axınını 2–3 razılıq verən testçi ilə yoxla; testçi yoxdursa simulyasiya kimi göstər.\n\n## Pulsuz platformalar və istifadə qaydası\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. `npx expo start` ilə lokal React Native demo aç, Expo Go-da test et; app-store/EAS ödənişi lazım deyil.\n- **Google Docs (personal)** — https://docs.google.com/document/. Boş sənəd aç, məqsəd/nəticə/cədvəl bölmələrini qur və lazım olduqda PDF ixrac et.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / mobile-development / task-9` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. Tapşırığı tap → aç → təqdim et üzrə 3 neytral test sualı hazırla. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. İcazə ilə ekran qeydlərini anonimləşdir, şəxsi data toplama. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. Müşahidələri problem, təsir, həll kimi qruplaşdır və iki düzəliş seç. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: Bir istifadəçi axınını 2–3 razılıq verən testçi ilə yoxla; testçi yoxdursa simulyasiya kimi göstər. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\nBir istifadəçi axınını 2–3 razılıq verən testçi ilə yoxla; testçi yoxdursa simulyasiya kimi göstər.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nMobil tətbiqin əsas axınını real istifadəçilərlə yoxlayıb anlaşılmayan addımları tapacaqsan.\n\n## 2. Başlamazdan əvvəl\nÖz işlək prototip/tətbiqin, neytral test tapşırıqları və razılıq alma qaydası. Mümkünsə 3–5 iştirakçı ilə sına.\n\n## 3. Addım-addım icra\n1. Öz mobil layihəni davam etdir.\n2. Task tapmaq, detallara baxmaq və həll təqdim etmək üçün 3 test ssenarisi yaz.\n3. İştirakçıdan tətbiqi özünün istifadə etməsini istə; addımları izah edib cavabı yönləndirmə.\n4. Vaxt, səhv klik və kömək ehtiyacını anonim qeyd et.\n5. Ən azı 5 tapıntını təsirə görə sırala.\n6. Bir düzəliş et və retest nəticəsini qeyd et.\n\n## 4. Konkret nümunə və izah\nNeytral ssenari: “Dizayn tapşırığını tap və hansı linki təqdim etməli olduğunu müəyyən et”. İştirakçıya hansı düyməni basacağını demə. İştirakçı tapılmırsa, öz ekspert yoxlamanı ayrıca qeyd et; istifadəçi testi apardığını iddia etmə.\n\n## 5. Nə təhvil verməlisən?\nTest planı, iştirakçı sayı, anonim müşahidələr, 5+ tapıntı, düzəliş və retest sübutu. Razılıq olmadan qeyd aparma və lazımsız şəxsi məlumat toplama.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nİştirakçı sayı və razılıq üsulu, 3 ssenari, anonim müşahidələr, prioritetlər və bir düzəlişin təkrar yoxlaması var. Müşahidə ilə fərziyyə ayrılıb.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Review the task flow with consenting test users or clearly label a simulated walkthrough.\n\n## Free tools and platforms — how to use them\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. Run a local React Native demo with Expo Go; paid store publishing or EAS is not required.\n- **Google Docs (personal)** — https://docs.google.com/document/. Create a document with goals, evidence, tables and a PDF export when needed.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / mobile-development / task-9` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Prepare three neutral tasks covering find → open → submit. Show evidence in a real screen, prototype, source file or test.\n4. Obtain consent and anonymize any collected notes; avoid private data. Show evidence in a real screen, prototype, source file or test.\n5. Group observations into issue/impact/fix and prioritize two improvements. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Review the task flow with consenting test users or clearly label a simulated walkthrough. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nReview the task flow with consenting test users or clearly label a simulated walkthrough.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nTest the mobile app's main flow with users and identify confusing steps.\n\n## 2. Before you start\nYour working prototype/app, neutral test tasks, and consent basics. Aim for three to five participants when possible.\n\n## 3. Step-by-step work\n1. Continue your own mobile project.\n2. Write three test scenarios: find a task, view details, and submit a solution.\n3. Ask participants to use the app themselves; do not guide their answers.\n4. Record time, misclicks, and requests for help anonymously.\n5. Rank at least five findings by impact.\n6. Make one improvement and record the retest result.\n\n## 4. Concrete example and explanation\nNeutral scenario: “Find the design task and determine which link to submit.” Do not tell participants which button to press. If no participant is available, label an expert walkthrough honestly.\n\n## 5. What to submit\nA test plan, participant count, anonymized observations, five or more findings, a fix, and retest evidence. Do not record without consent or collect unnecessary personal data.\n\n## 6. How to check your work\nReport participant count/consent, three scenarios, anonymous observations, priorities, and a retest of one fix. Separate observation from assumption."},{"slug":"mobile-development","task_number":10,"title":"Final Mobile App","old_description":"[[AZ]]\nTapşırıqları idarə edən tamamlanmış mobil app-i API, offline davranış, test və handoff sənədi ilə təqdim et.\n\n[[EN]]\nDeliver a complete task-management mobile app with API, offline behavior, tests, and handoff documentation.","old_instructions":"[[AZ]]\n## 1. Bu tapşırıq nə üçündür?\nƏvvəlki tapşırıqları birləşdirib quraşdırıla bilən, test edilmiş və sənədləşdirilmiş mobil tətbiq təqdim edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz Tapşırıq 1–9 layihən, navigation, reusable components, API states, storage, form validation və testlər.\n\n## 3. Addım-addım icra\n1. Əvvəlki mobil tapşırıqlarındakı öz repo-nu davam etdir.\n2. Naviqasiya, task list/detail, search/filter və submission axınını birləşdir.\n3. Loading, empty, error və offline vəziyyətlərini əlavə et.\n4. Həssas olmayan seçimi saxla və form validation-u yoxla.\n5. Ən azı 8 uyğun test yaz və cihaz/emulatorda əsas axını yoxla.\n6. Fresh setup addımları, screenshot-lar, məlum məhdudiyyətlər və qısa demo əlavə et.\n\n## 4. Konkret nümunə və izah\nTam demo axını: tapşırıq axtar → statusla filtr et → detalı oxu → uydurma həll linki göndər → uğur mesajını gör. Sonra şəbəkə xətası və offline vəziyyəti göstər. Tətbiq mağazasında dərc etmək tələb olunmur.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işləyən Expo tətbiqi, test nəticələri, ekran görüntüləri və README. Quraşdırma təlimatı təkrarlana bilməli, secret-lər repo-da olmamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nTəmiz quraşdırma və əsas axın cihazda təkrarlanır. Səkkiz test, ekran görüntüləri və məlum məhdudiyyətlər var; həssas konfiqurasiya paylaşılmır.\n\n[[EN]]\n## 1. Goal\nCombine earlier work into a runnable, tested, and documented mobile application.\n\n## 2. Before you start\nYour own project from Tasks 1–9: navigation, reusable components, API states, storage, form validation, and tests.\n\n## 3. Step-by-step work\n1. Continue your own repository from earlier mobile tasks.\n2. Combine navigation, task list/detail, search/filter, and submission.\n3. Include loading, empty, error, and offline states.\n4. Persist a non-sensitive preference and verify form validation.\n5. Write at least eight relevant tests and check the main flow on a device/emulator.\n6. Add fresh-setup instructions, screenshots, known limitations, and a short demo.\n\n## 4. Concrete example and explanation\nDemo: search → filter → read detail → submit a fictional solution URL → success. Then demonstrate failure and offline states. App-store publication is not required.\n\n## 5. What to submit\nYour own GitHub repository link, working Expo app, test results, screenshots, and README. Setup must be repeatable and the repository must contain no secrets.\n\n## 6. How to check your work\nReproduce setup and the main flow on a device. Include eight tests, screenshots, and limitations without exposing sensitive configuration.","new_description":"[[AZ]]\nTapşırıqları idarə edən tamamlanmış mobil app-i API, offline davranış, test və handoff sənədi ilə təqdim et.\n\nPulsuz alətlər: Node.js (free), Expo Go / Expo CLI (free local), GitHub Free. Yeni sadə bələdçi tapşırığın içindədir.\n\n[[EN]]\nDeliver a complete task-management mobile app with API, offline behavior, tests, and handoff documentation.\n\nFree tools: Node.js (free), Expo Go / Expo CLI (free local), GitHub Free. The beginner guide is included in the task.","new_instructions":"[[AZ]]\n## Bu tapşırığı ilk dəfə edən tələbə üçün izah\nSəndən əsasən **real ekran, işləyən demo, araşdırma sənədi və ya prototip** hazırlamağın gözlənilir. **Sadə nümunə:** Expo Go-da açılan 8 ekranlı demo, README, mock data və test sübutlarını birləşdir.\n\n## Pulsuz platformalar və istifadə qaydası\n- **Node.js (free)** — https://nodejs.org. Lokal JavaScript/TypeScript mühiti qur, paketləri quraşdır və development server aç.\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. `npx expo start` ilə lokal React Native demo aç, Expo Go-da test et; app-store/EAS ödənişi lazım deyil.\n- **GitHub Free** — https://github.com. README və nümunə kod üçün şəxsi repo yarat; token və şəxsi data yükləmə.\n> Pullu app-store qeydiyyatı, premium dizayn elementi, ödənişli xidmət və ya API açarı lazım deyil. Free planın limiti dəyişirsə, uyğun pulsuz lokal alternativ seç. Real şəxsi məlumat toplama.\n\n## Addım-addım icra: 8 mərhələ\n1. Öz `Talora / mobile-development / task-10` qovluğunu hazırla. Pulsuz dizayn/redaktor/telefon alətini aç, əvvəlki işləri varsa kopyala.\n2. Kim üçün işlədiyini, hansı problemi həll etdiyini və nəticəni necə yoxlayacağını sadə cümlə ilə yaz.\n3. Əvvəlki ekran, API mock, offline və validation hissələrini birləşdir. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n4. Sıfırdan quraşdırma və 5 əsas istifadə axınını yoxla. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n5. Source code, demo görüntü və məlum məhdudiyyətləri təhvil ver; real hesab məlumatı daxil etmə. Nəticəni konkret ekran, prototip, mənbə faylı və ya testlə göstər.\n6. Praktik ssenari: Expo Go-da açılan 8 ekranlı demo, README, mock data və test sübutlarını birləşdir. Bir normal və bir səhv/boş halı sınayıb ekran görüntüsü və ya qısa qeyd saxla.\n7. Əvvəlki rəsmi şərtlərdə yazılan formatda fayl, dizayn/prototip linki və ya GitHub repo hazırla; istifadə etdiyin alətləri və mənbələri göstər.\n8. İşin 8 addımını və aşağıdakı orijinal şərtləri yoxla. 3–5 cümləlik nəticəni yaz, link icazələrini sına.\n\n## Praktik nümunənin gözlənilən nəticəsi\nExpo Go-da açılan 8 ekranlı demo, README, mock data və test sübutlarını birləşdir.\nMəzmunu öz uydurma istifadəçi ssenarinə uyğunlaşdır və nəyi yoxladığını göstər. Real araşdırma və simulyasiyanı qarışdırma.\n\n## Nəyi təqdim etməlisən?\n- Əvvəlki rəsmi tapşırıqda tələb olunan dəqiq **fayl və ya link**; həmin hissə dəyişməyib.\n- Redaktə olunan layihə faylı, uyğun screenshot/prototip, test qeydi və qısa izahlı README.\n- 3–5 cümləlik nəticə və istifadə etdiyin pulsuz alətlərin, icazəli media mənbələrinin adları.\n- Heç bir şəxsi məlumat, şifrə, real müştəri məlumatı və ya icazəsiz kontent göndərmə.\n\n## Özünü yoxlama üçün 100 ballıq nümunə\n- **40 bal:** ekran/flow/funksiya və orijinal tələb olunan nəticələr tamamdır.\n- **25 bal:** praktiki ssenari işləyir, boş/xəta halları yoxlanılıb.\n- **15 bal:** dizayn və mətn oxunaqlıdır, fayllar və README aydındır.\n- **10 bal:** əlçatanlıq, məxfilik, müəllif hüququ və pulsuz alətlər nəzərə alınıb.\n- **10 bal:** öz izahın, məhdudiyyətlər və təkmilləşdirmələr yazılıb.\n**Bu rubrik tədris bələdçisidir, əvvəldən qiymətləndirilən işləri və rəsmi şərtləri dəyişmir.**\n\n## Son yoxlama\n- Ölçülər, əsas addımlar, fayl giriş icazələri sınaqdan keçirilib.\n- Demo üçün sintetik/razılıqlı məlumatdan istifadə olunub.\n- Orijinal tələb olunan təqdimat növü və meyarlar qorunub.\n\n## Əvvəlki rəsmi tapşırıq tələbləri (qorunur)\n## 1. Bu tapşırıq nə üçündür?\nƏvvəlki tapşırıqları birləşdirib quraşdırıla bilən, test edilmiş və sənədləşdirilmiş mobil tətbiq təqdim edəcəksən.\n\n## 2. Başlamazdan əvvəl\nÖz Tapşırıq 1–9 layihən, navigation, reusable components, API states, storage, form validation və testlər.\n\n## 3. Addım-addım icra\n1. Əvvəlki mobil tapşırıqlarındakı öz repo-nu davam etdir.\n2. Naviqasiya, task list/detail, search/filter və submission axınını birləşdir.\n3. Loading, empty, error və offline vəziyyətlərini əlavə et.\n4. Həssas olmayan seçimi saxla və form validation-u yoxla.\n5. Ən azı 8 uyğun test yaz və cihaz/emulatorda əsas axını yoxla.\n6. Fresh setup addımları, screenshot-lar, məlum məhdudiyyətlər və qısa demo əlavə et.\n\n## 4. Konkret nümunə və izah\nTam demo axını: tapşırıq axtar → statusla filtr et → detalı oxu → uydurma həll linki göndər → uğur mesajını gör. Sonra şəbəkə xətası və offline vəziyyəti göstər. Tətbiq mağazasında dərc etmək tələb olunmur.\n\n## 5. Nə təhvil verməlisən?\nÖz GitHub repo linkin, işləyən Expo tətbiqi, test nəticələri, ekran görüntüləri və README. Quraşdırma təlimatı təkrarlana bilməli, secret-lər repo-da olmamalıdır.\n\n## 6. Hazır olduğunu necə yoxlamalısan?\nTəmiz quraşdırma və əsas axın cihazda təkrarlanır. Səkkiz test, ekran görüntüləri və məlum məhdudiyyətlər var; həssas konfiqurasiya paylaşılmır.\n\n[[EN]]\n## Beginner-friendly explanation\nYou should produce **a tangible screen, working demo, research document or prototype**. **Example:** Package the demo app, README, mock data and screenshots, without paid store publishing.\n\n## Free tools and platforms — how to use them\n- **Node.js (free)** — https://nodejs.org. Install a local JavaScript/TypeScript runtime and run your development server.\n- **Expo Go / Expo CLI (free local)** — https://docs.expo.dev. Run a local React Native demo with Expo Go; paid store publishing or EAS is not required.\n- **GitHub Free** — https://github.com. Use a free repository with README and sample code; never commit secrets or personal data.\n> No paid app-store registration, premium design assets, paid services or paid API keys are required. Free-tier limits may vary; use appropriate local alternatives. Avoid collecting private information.\n\n## Eight step-by-step stages\n1. Prepare a `Talora / mobile-development / task-10` folder; open your free design/editor/phone tools and reuse previous source work.\n2. Explain the intended user, problem and a measurable success condition in plain language.\n3. Integrate earlier screens, mock API, offline behavior and validation. Show evidence in a real screen, prototype, source file or test.\n4. Run clean setup and test five common user journeys. Show evidence in a real screen, prototype, source file or test.\n5. Deliver source, demo evidence and known limitations without real user data. Show evidence in a real screen, prototype, source file or test.\n6. Test this scenario: Package the demo app, README, mock data and screenshots, without paid store publishing. Check a normal and invalid/empty state and capture evidence.\n7. Prepare the exact originally required source file, design/prototype link or GitHub repository; list tools and assets.\n8. Check all eight steps and the unchanged official criteria; add three to five sentences on the result and verify shared links.\n\n## Worked example: expected outcome\nPackage the demo app, README, mock data and screenshots, without paid store publishing.\nAdapt the example to your fictional learner/user scenario and show how you tested it. Distinguish real research from simulation.\n\n## What to submit\n- The exact **file or link** required by the original official task below.\n- Editable sources, suitable screenshots/prototypes, test notes and a short README.\n- A three-to-five sentence explanation and a list of free tools and properly licensed assets.\n- Do not disclose personal data, passwords, real customer records or unauthorized content.\n\n## Illustrative 100-point self-check\n- **40:** core screens/flows/functionality and unchanged original deliverables.\n- **25:** tested behavior, normal and empty/error states.\n- **15:** legibility, file organization and understandable README.\n- **10:** accessibility, privacy, copyright and free tools.\n- **10:** reasoning, limitations and possible improvements.\n**This is educational guidance, not a change to existing official criteria or historical grades.**\n\n## Final checklist\n- Test responsive sizes, interactions and shared-link permissions.\n- Use fictional or consented data only.\n- Preserve the original submission type and acceptance criteria.\n\n## Original official requirements (preserved)\n## 1. Goal\nCombine earlier work into a runnable, tested, and documented mobile application.\n\n## 2. Before you start\nYour own project from Tasks 1–9: navigation, reusable components, API states, storage, form validation, and tests.\n\n## 3. Step-by-step work\n1. Continue your own repository from earlier mobile tasks.\n2. Combine navigation, task list/detail, search/filter, and submission.\n3. Include loading, empty, error, and offline states.\n4. Persist a non-sensitive preference and verify form validation.\n5. Write at least eight relevant tests and check the main flow on a device/emulator.\n6. Add fresh-setup instructions, screenshots, known limitations, and a short demo.\n\n## 4. Concrete example and explanation\nDemo: search → filter → read detail → submit a fictional solution URL → success. Then demonstrate failure and offline states. App-store publication is not required.\n\n## 5. What to submit\nYour own GitHub repository link, working Expo app, test results, screenshots, and README. Setup must be repeatable and the repository must contain no secrets.\n\n## 6. How to check your work\nReproduce setup and the main flow on a device. Include eight tests, screenshots, and limitations without exposing sensitive configuration."}]$legacy_payload$::jsonb);
DO $preflight$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE i.slug='mobile-development' AND t.title=e.item->>'title' AND t.instructions=e.item->>'old_instructions'
 AND t.description=e.item->>'old_description' AND t.status='published' AND t.is_required;
 IF (SELECT jsonb_array_length(payload) FROM legacy_guides)<>10 OR n<>10 THEN RAISE EXCEPTION 'Original version mismatch in mobile-development: %',n; END IF;
END; $preflight$;
DO $apply$
DECLARE n integer;
BEGIN
 UPDATE public.internship_tasks t SET instructions=e.item->>'new_instructions',description=e.item->>'new_description'
 FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 WHERE i.slug='mobile-development' AND t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 AND t.title=e.item->>'title' AND t.instructions=e.item->>'old_instructions' AND t.description=e.item->>'old_description';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>10 THEN RAISE EXCEPTION 'Only % tasks updated for mobile-development',n; END IF;
END; $apply$;
DO $verify$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM legacy_guides src CROSS JOIN LATERAL jsonb_array_elements(src.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE i.slug='mobile-development' AND t.instructions=e.item->>'new_instructions' AND t.description=e.item->>'new_description'
 AND t.status='published' AND t.is_required;
 IF n<>10 THEN RAISE EXCEPTION 'Post-update mismatch in mobile-development: %',n; END IF;
END; $verify$;
COMMIT;
